<file path="src/invoices.js">
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a new draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customer = getCustomer(customerId);
  if (!customer.ok) return customer;

  // Validate issueDate is in YYYY-MM-DD format and is a real date
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate ?? '')) return fail('DATE_INVALID');
  const [year, month, day] = issueDate.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() + 1 !== month || date.getDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines is a non-empty array
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Get product and enrich line
    const product = getProduct(line.sku);
    if (!product.ok) return product;

    enrichedLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
    });
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total amount for a line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || !Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
  if (!Number.isInteger(line.unitPrice) || line.unitPrice < 0) return fail('AMOUNT_INVALID');
  return ok(line.qty * line.unitPrice);
}

/**
 * Calculate subtotal and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }}
 * @returns {{ ok: true, value: { subtotal: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines) || invoice.lines.length === 0) return fail('NO_LINES');

  let subtotal = 0;
  for (const line of invoice.lines) {
    const lt = lineTotal(line);
    if (!lt.ok) return lt;
    subtotal += lt.value;
  }

  return ok({ subtotal, total: subtotal });
}

/**
 * Add or increment a line on a draft invoice.
 * @param {object} invoice
 * @param {{ sku: string, qty: number }}
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Validate invoice is draft
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get product
  const product = getProduct(sku);
  if (!product.ok) return product;

  // Check if line with this SKU already exists
  const existingLine = invoice.lines.find((l) => l.sku === sku);
  const newLines = existingLine
    ? invoice.lines.map((l) =>
        l.sku === sku
          ? {
              ...l,
              qty: l.qty + qty,
            }
          : l
      )
    : [
        ...invoice.lines,
        {
          sku,
          name: product.value.name,
          qty,
          unitPrice: product.value.unitPrice,
          vatRate: product.value.vatRate,
        },
      ];

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {object} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Validate invoice is draft
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove the line
  const newLines = invoice.lines.filter((l) => l.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {object} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Validate invoice is draft
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  const newInvoice = {
    ...invoice,
    number: numberResult.value,
    status: 'issued',
  };

  return ok(newInvoice);
}
</file>

<file path="src/money.js">
import { ok, fail } from './result.js';

/**
 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
 * @param {number} x
 * @returns {number}
 */
export function roundCents(x) {
  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

/**
 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
 * @param {number} cents
 * @returns {string}
 */
export function formatEuros(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
}

/**
 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
 * @param {string} text
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function parseEuros(text) {
  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
  if (!m) return fail('AMOUNT_INVALID');
  const euros = Number(m[1].replace(/,/g, ''));
  const cents = Number((m[2] ?? '').padEnd(2, '0'));
  return ok(euros * 100 + cents);
}
</file>

<file path="src/numbering.js">
import { ok, fail } from './result.js';

/**
 * Calculate the next invoice number for a given date.
 * Format: INV-<year>-<counter> where counter is 4 digits, restarting each year.
 * @param {Array<string>} existingNumbers
 * @param {string} issueDate
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  // Validate date format and reality
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate ?? '')) return fail('DATE_INVALID');
  const [year, month, day] = issueDate.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() + 1 !== month || date.getDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Find all numbers for this year
  const pattern = new RegExp(`^INV-${year}-(\\d{4})$`);
  const yearCounters = existingNumbers
    .filter((num) => pattern.test(num))
    .map((num) => {
      const match = pattern.exec(num);
      return parseInt(match[1], 10);
    });

  // Find the next counter
  const maxCounter = yearCounters.length === 0 ? 0 : Math.max(...yearCounters);
  const nextCounter = maxCounter + 1;

  // Validate counter doesn't exceed 9999
  if (nextCounter > 9999) return fail('TOO_MANY_INVOICES');

  const number = `INV-${year}-${String(nextCounter).padStart(4, '0')}`;
  return ok(number);
}
</file>

<file path="src/render.js">
import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { formatEuros } from './money.js';
import { ok, fail } from './result.js';

/**
 * Render an invoice as plain text for display to customers.
 * @param {object} invoice
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function renderInvoiceText(invoice) {
  // Validate invoice
  if (!invoice || !invoice.customerId) return fail('CUSTOMER_NOT_FOUND');

  // Get customer
  const customer = getCustomer(invoice.customerId);
  if (!customer.ok) return customer;

  // Calculate totals
  const totals = invoiceTotals(invoice);
  if (!totals.ok) return totals;

  // Build invoice text
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ? invoice.number : 'DRAFT');

  // Customer name
  lines.push(customer.value.name);

  // Line items
  for (const line of invoice.lines) {
    const total = line.qty * line.unitPrice;
    lines.push(
      `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`
    );
  }

  // Total
  lines.push(`Total: ${formatEuros(totals.value.total)}`);

  return ok(lines.join('\n'));
}
</file>

<file path="src/result.js">
/**
 * A successful result.
 * @template T
 * @param {T} value
 * @returns {{ ok: true, value: T }}
 */
export function ok(value) {
  return { ok: true, value };
}

/**
 * A failed result. `error` is an error code from ERRORS in src/errors.js.
 * @param {string} error
 * @param {unknown} [details]
 * @returns {{ ok: false, error: string, details?: unknown }}
 */
export function fail(error, details) {
  return details === undefined ? { ok: false, error } : { ok: false, error, details };
}
</file>

